<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';sessionInit();$error='';$done=false;
if(schemaNumber()!==SCHEMA_VERSION){http_response_code(503);exit('Activation indisponible pendant la mise à jour.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
    checkCsrf();$key=hash('sha256','activation|'.($_SERVER['REMOTE_ADDR']??''));query('INSERT INTO login_attempts(attempt_key,attempts,window_start) VALUES(?,1,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE attempts=IF(window_start<UTC_TIMESTAMP()-INTERVAL 15 MINUTE,1,attempts+1),window_start=IF(window_start<UTC_TIMESTAMP()-INTERVAL 15 MINUTE,UTC_TIMESTAMP(),window_start)',[$key]);
    try{
        if((int)scalar('SELECT attempts FROM login_attempts WHERE attempt_key=?',[$key])>8){http_response_code(429);throw new DomainException('Trop de tentatives. Réessayez dans 15 minutes.');}
        $email=strtolower(emailField('email'));$code=field('code',64,true);$password=(string)($_POST['password']??'');if(strlen($password)<12||strlen($password)>72||$password!==(string)($_POST['confirm_password']??''))throw new DomainException('Choisissez et confirmez un mot de passe de 12 à 72 caractères.');
        db()->beginTransaction();$u=row('SELECT * FROM users WHERE email=? FOR UPDATE',[$email]);
        if(!$u||!$u['is_active']||!$u['activation_hash']||!hash_equals($u['activation_hash'],hash('sha256',$code))||$u['activation_expires']<gmdate('Y-m-d H:i:s')||!$u['employee_id']||!row("SELECT id FROM employees WHERE id=? AND archived=0 AND employment_state='Actif'",[$u['employee_id']]))throw new DomainException('Activation impossible. Vérifiez le code ou demandez un nouveau code à l’administrateur.');
        query('UPDATE users SET password_hash=?,activation_hash=NULL,activation_expires=NULL,session_version=session_version+1 WHERE id=?',[password_hash($password,PASSWORD_DEFAULT),$u['id']]);audit('Compte activé','compte',(int)$u['id']);db()->commit();$done=true;
    }catch(DomainException $ex){if(db()->inTransaction())db()->rollBack();$error=$ex->getMessage();}
}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activer mon compte · CMYK Designs</title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-body"><main class="auth-card"><div class="brand-text">CMYK<span>designs.</span></div><h1><?=$done?'Compte activé.':'Activer mon compte.'?></h1><p class="muted">Utilisez le code de 24 heures communiqué personnellement par votre administrateur.</p><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif?><?php if($done):?><a class="btn primary" href="index.php">Me connecter</a><?php else:?><form method="post" class="form-stack"><?=csrf()?><label>E-mail<input type="email" name="email" required maxlength="190" autocomplete="username"></label><label>Code d’activation<input name="code" required minlength="64" maxlength="64" autocomplete="off"></label><label>Mon mot de passe<input type="password" name="password" required minlength="12" maxlength="72" autocomplete="new-password"></label><label>Confirmer<input type="password" name="confirm_password" required minlength="12" maxlength="72" autocomplete="new-password"></label><button class="btn primary">Activer mon accès</button></form><?php endif?></main></body></html>
